#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    constexpr size_t MAX_FRAME = 32;
    char nomi[MAX_FRAME][32];
    size_t dim_frame[MAX_FRAME] = {0};
    char riga[128], cmd[16], nome[32];
    int lim_in = 0, byte_in = 0;
    char extra = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &lim_in, &extra) != 1 || lim_in < 1 || lim_in > 1'000'000) {
        fprintf(stderr, "Errore: limite stack non valido.\n");
        return EXIT_FAILURE;
    }
    size_t limite = (size_t)lim_in, prof = 0, usati = 0, picco = 0, heap_tot = 0;

    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        if (strcmp(cmd, "CALL") == 0) {
            if (sscanf(riga, "CALL %31s %d %c", nome, &byte_in, &extra) != 2 ||
                byte_in < 1 || byte_in > 1'000'000) {
                fprintf(stderr, "Errore: comando CALL non valido.\n");
                return EXIT_FAILURE;
            }
            size_t dim = (size_t)byte_in;
            if (prof == MAX_FRAME || dim > limite - usati) {
                printf("STACK OVERFLOW: %s richiede %zu B (disponibili %zu B)\n",
                       nome, dim, limite - usati);
            } else {
                strcpy(nomi[prof], nome);
                dim_frame[prof++] = dim;
                usati += dim;
                if (usati > picco) { picco = usati; }
                printf("CALL %s (+%zu B) -> stack=%zu/%zu B\n", nome, dim, usati, limite);
            }
        } else if (strcmp(cmd, "RET") == 0 && sscanf(riga, "RET %c", &extra) != 1) {
            if (prof == 0) {
                printf("ERRORE: stack vuoto\n");
            } else {
                --prof;
                usati -= dim_frame[prof];
                printf("RET %s (-%zu B) -> stack=%zu/%zu B\n",
                       nomi[prof], dim_frame[prof], usati, limite);
            }
        } else if (strcmp(cmd, "HEAP") == 0) {
            if (sscanf(riga, "HEAP %31s %d %c", nome, &byte_in, &extra) != 2 ||
                byte_in < 1 || byte_in > 1'000'000) {
                fprintf(stderr, "Errore: comando HEAP non valido.\n");
                return EXIT_FAILURE;
            }
            heap_tot += (size_t)byte_in;
            printf("HEAP %s (+%d B) -> heap=%zu B\n", nome, byte_in, heap_tot);
        } else {
            fprintf(stderr, "Errore: comando sconosciuto.\n");
            return EXIT_FAILURE;
        }
    }
    printf("Picco stack: %zu B\nFrame rimasti sullo stack: %zu\nTotale richiesto sullo heap: %zu B\n",
           picco, prof, heap_tot);
    return EXIT_SUCCESS;
}

#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void errore_fatale(const char *messaggio);

int main(void) {
    char riga[128], buf_nome[64];
    int n_in = 0, k_in = 0;
    char extra = '\0';

    if (fgets(buf_nome, (int)sizeof(buf_nome), stdin) == nullptr) {
        errore_fatale("etichetta mancante.");
    }
    buf_nome[strcspn(buf_nome, "\n")] = '\0';
    if (buf_nome[0] == '\0') { errore_fatale("etichetta vuota."); }
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %d %c", &n_in, &k_in, &extra) != 2 ||
        n_in < 1 || n_in > 1000 || k_in < 1 || k_in > 63) {
        errore_fatale("parametri n o k non validi.");
    }
    size_t n = (size_t)n_in, k = (size_t)k_in;
    char *nome = strdup(buf_nome);
    char *codice = strndup(buf_nome, k);
    int *punteggi = malloc(n * sizeof(*punteggi));
    int *freq = calloc(101, sizeof(*freq));
    if (nome == nullptr || codice == nullptr || punteggi == nullptr || freq == nullptr) {
        free(nome); free(codice); free(punteggi); free(freq);
        errore_fatale("allocazione memoria fallita.");
    }
    long long somma = 0;
    for (size_t i = 0; i < n; ++i) {
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%d %c", &punteggi[i], &extra) != 1 ||
            punteggi[i] < 0 || punteggi[i] > 100) {
            free(nome); free(codice); free(punteggi); free(freq);
            errore_fatale("punteggio non valido (atteso 0..100).");
        }
        somma += punteggi[i];
        ++freq[punteggi[i]];
    }
    int minimo = punteggi[0], massimo = punteggi[0], modale = 0, distinti = 0;
    for (size_t i = 1; i < n; ++i) {
        if (punteggi[i] < minimo) { minimo = punteggi[i]; }
        if (punteggi[i] > massimo) { massimo = punteggi[i]; }
    }
    for (int v = 0; v <= 100; ++v) {
        if (freq[v] > 0) { ++distinti; }
        if (freq[v] > freq[modale]) { modale = v; }
    }
    printf("Etichetta: %s (codice: %s)\n", nome, codice);
    printf("Campioni: %zu, distinti: %d\n", n, distinti);
    printf("Min: %d, max: %d, media: %.2f\n", minimo, massimo, (double)somma / (double)n);
    printf("Punteggio piu frequente: %d (%d volte)\n", modale, freq[modale]);
    free(nome); nome = nullptr;
    free(codice); codice = nullptr;
    free(punteggi); punteggi = nullptr;
    free(freq); freq = nullptr;
    return EXIT_SUCCESS;
}

void errore_fatale(const char *messaggio) {
    fprintf(stderr, "Errore: %s\n", messaggio);
    exit(EXIT_FAILURE);
}

#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    char riga[128];
    int soglia = 0, valore = 0;
    char extra = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &soglia, &extra) != 1) {
        fprintf(stderr, "Errore: soglia non valida.\n");
        return EXIT_FAILURE;
    }

    int *dati = nullptr;
    size_t len = 0, cap = 0, ridim = 0;
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%d %c", &valore, &extra) != 1 ||
            valore < -100'000 || valore > 100'000) {
            free(dati);
            fprintf(stderr, "Errore: valore non valido.\n");
            return EXIT_FAILURE;
        }
        if (len == cap) {
            size_t nuova_cap = (cap == 0) ? 2 : cap * 2;
            int *tmp = realloc(dati, nuova_cap * sizeof(*dati));
            if (tmp == nullptr) {
                free(dati);
                fprintf(stderr, "Errore: riallocazione fallita.\n");
                return EXIT_FAILURE;
            }
            dati = tmp;
            cap = nuova_cap;
            ++ridim;
        }
        dati[len++] = valore;
    }
    size_t cap_picco = cap;
    size_t len_filt = 0;
    long long somma = 0;
    for (size_t i = 0; i < len; ++i) {
        if (dati[i] >= soglia) {
            dati[len_filt++] = dati[i];
            somma += dati[i];
        }
    }
    if (len_filt == 0) {
        free(dati); dati = nullptr; cap = 0;
    } else if (len_filt < cap) {
        int *tmp = realloc(dati, len_filt * sizeof(*dati));
        if (tmp != nullptr) { dati = tmp; cap = len_filt; }
    }
    printf("Letti: %zu, capacita picco: %zu, ridimensionamenti: %zu\n", len, cap_picco, ridim);
    printf("Capacita finale: %zu, filtrati (>= %d): %zu\n", cap, soglia, len_filt);
    if (len_filt == 0) {
        printf("Valori: (nessuno)\n");
    } else {
        printf("Valori:");
        for (size_t i = 0; i < len_filt; ++i) { printf(" %d", dati[i]); }
        printf("\nSomma filtrati: %lld\n", somma);
    }
    free(dati); dati = nullptr;
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char riga[128];
    char *attivo = nullptr, *backup = nullptr;

    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        riga[strcspn(riga, "\n")] = '\0';
        if (riga[0] == '\0') { continue; }
        if (strncmp(riga, "IMPOSTA ", 8) == 0 && riga[8] != '\0') {
            char *copia = strdup(riga + 8);
            if (copia == nullptr) {
                free(attivo); free(backup);
                fprintf(stderr, "Errore: allocazione fallita.\n");
                return EXIT_FAILURE;
            }
            free(attivo);
            attivo = copia;
            printf("Attivo impostato: [%s]\n", attivo);
        } else if (strcmp(riga, "BACKUP") == 0) {
            if (attivo == nullptr) {
                printf("Backup impossibile: attivo vuoto\n");
            } else {
                char *copia = strdup(attivo);
                if (copia == nullptr) {
                    free(attivo); free(backup);
                    fprintf(stderr, "Errore: allocazione fallita.\n");
                    return EXIT_FAILURE;
                }
                free(backup);
                backup = copia;
                printf("Backup salvato: [%s]\n", backup);
            }
        } else if (strcmp(riga, "RIPRISTINA") == 0) {
            if (backup == nullptr) {
                printf("Ripristino impossibile: backup vuoto\n");
            } else {
                char *copia = strdup(backup);
                if (copia == nullptr) {
                    free(attivo); free(backup);
                    fprintf(stderr, "Errore: allocazione fallita.\n");
                    return EXIT_FAILURE;
                }
                free(attivo);
                attivo = copia;
                printf("Attivo ripristinato: [%s]\n", attivo);
            }
        } else if (strcmp(riga, "SVUOTA A") == 0) {
            if (attivo == nullptr) { printf("Attivo gia vuoto\n"); }
            else { free(attivo); attivo = nullptr; printf("Attivo svuotato\n"); }
        } else if (strcmp(riga, "SVUOTA B") == 0) {
            if (backup == nullptr) { printf("Backup gia vuoto\n"); }
            else { free(backup); backup = nullptr; printf("Backup svuotato\n"); }
        } else if (strcmp(riga, "STATO") == 0) {
            printf("Stato -> attivo=[%s], backup=[%s]\n",
                   attivo != nullptr ? attivo : "vuoto",
                   backup != nullptr ? backup : "vuoto");
        } else {
            free(attivo); free(backup);
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    int rilasciati = (attivo != nullptr ? 1 : 0) + (backup != nullptr ? 1 : 0);
    free(attivo); attivo = nullptr;
    free(backup); backup = nullptr;
    printf("Buffer rilasciati alla chiusura: %d\n", rilasciati);
    return EXIT_SUCCESS;
}

#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char testo[256], sep[16], riga[128];
    if (fgets(testo, (int)sizeof(testo), stdin) == nullptr ||
        fgets(sep, (int)sizeof(sep), stdin) == nullptr) {
        fprintf(stderr, "Errore: testo o separatore mancante.\n");
        return EXIT_FAILURE;
    }
    testo[strcspn(testo, "\n")] = '\0';
    sep[strcspn(sep, "\n")] = '\0';
    size_t len_testo = strlen(testo), len_sep = strlen(sep);
    if (len_testo == 0) {
        fprintf(stderr, "Errore: testo vuoto.\n");
        return EXIT_FAILURE;
    }
    char *risultato = nullptr;
    size_t len_ris = 0;
    int validi = 0, scartati = 0, inizio = 0, lunghezza = 0;
    char extra = '\0';

    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%d %d %c", &inizio, &lunghezza, &extra) != 2) {
            free(risultato);
            fprintf(stderr, "Errore: richiesta non valida.\n");
            return EXIT_FAILURE;
        }
        if (inizio < 0 || lunghezza <= 0 || (size_t)inizio >= len_testo ||
            (size_t)lunghezza > len_testo - (size_t)inizio) {
            ++scartati;
            printf("Richiesta (%d, %d): fuori dai limiti\n", inizio, lunghezza);
            continue;
        }
        char *fetta = strndup(testo + inizio, (size_t)lunghezza);
        if (fetta == nullptr) {
            free(risultato);
            fprintf(stderr, "Errore: allocazione fetta fallita.\n");
            return EXIT_FAILURE;
        }
        size_t agg_sep = (validi > 0) ? len_sep : 0;
        size_t nuova_len = len_ris + agg_sep + (size_t)lunghezza;
        char *tmp = realloc(risultato, nuova_len + 1);
        if (tmp == nullptr) {
            free(fetta); free(risultato);
            fprintf(stderr, "Errore: riallocazione fallita.\n");
            return EXIT_FAILURE;
        }
        risultato = tmp;
        if (agg_sep > 0) { strcpy(risultato + len_ris, sep); }
        strcpy(risultato + len_ris + agg_sep, fetta);
        len_ris = nuova_len;
        ++validi;
        printf("Fetta %d: [%s]\n", validi, fetta);
        free(fetta); fetta = nullptr;
    }
    printf("Fette valide: %d, scartate: %d\n", validi, scartati);
    printf("Risultato (len=%zu): [%s]\n", len_ris, risultato != nullptr ? risultato : "");
    free(risultato); risultato = nullptr;
    return EXIT_SUCCESS;
}
